	private void assertCancellationDuringSort(boolean topK) throws Exception {
		CountDownLatch comparisonEntered = new CountDownLatch(1);
		CountDownLatch releaseComparison = new CountDownLatch(1);
		var source = SealedBoundaryTestSupport.source(data());
		BlockingOrderFunction function = new BlockingOrderFunction(comparisonEntered, releaseComparison,
				() -> source.opened > 0 && source.opened == source.closed);
		FunctionRegistry registry = FunctionRegistry.getInstance();
		Function previousFunction = registry.add(function).orElse(null);
		ExecutorService executor = Executors.newSingleThreadExecutor();
		CloseableIteration<BindingSet> result = null;
		try {
			var ordinary = SealedBoundaryTestSupport.ordinary(source, true);
			QueryRoot ordinaryRoot = root(function.getURI(), topK);
			QueryEvaluationStep ordinaryStep = ordinary.precompileFinalTupleResult(
					QueryEvaluationUtility.pinFunctions(ordinaryRoot));
			List<BindingSet> ordinaryRows = SealedBoundaryTestSupport.drain(ordinaryStep, EmptyBindingSet.getInstance(),
					false);
			assertEquals(topK ? 2 : 6, ordinaryRows.size(), "the ordinary modifier oracle returns its declared rows");
			assertEquals(source.opened, source.closed,
					"ordinary query reader closes before native cancellation control");

			function.blockNextComparison.set(true);
			var nativeStrategy = SealedBoundaryTestSupport.nativeStrategy(source, true);
			QueryRoot nativeRoot = root(function.getURI(), topK);
			Order order = topK ? (Order) ((Slice) nativeRoot.getArg()).getArg() : (Order) nativeRoot.getArg();
			order.setExecutionSummaryEnabled(true);
			nativeRoot.setExecutionSummaryEnabled(true);
			order.getArg().setExecutionSummaryEnabled(true);
			((Projection) order.getArg()).getArg().setExecutionSummaryEnabled(true);
			QueryEvaluationStep step = nativeStrategy
					.precompileFinalTupleResult(QueryEvaluationUtility.pinFunctions(nativeRoot));
			String plannedPlan = nativeRoot.getStringMetricPlanned(LmdbNativeExplain.PHYSICAL_PLAN);
			assertNotNull(plannedPlan, "the compiled public root has an ORDER physical plan");
			assertTrue(plannedPlan.contains("RootPipeline(stages=[")
					&& plannedPlan.contains(topK ? "TopK(" : "Order(keys="), plannedPlan);
			int openedBeforeNative = source.opened;
			result = step.evaluate(EmptyBindingSet.getInstance());
			CooperativeCancellation cancellation = assertInstanceOf(CooperativeCancellation.class, result);
			NativeExecutionContext owner = NativeExecutionContextCarrier.contextOf(result);
			assertNotNull(owner, "the evaluated ORDER result carries its actual query owner");
			List<BindingSet> emitted = new ArrayList<>();
			CloseableIteration<BindingSet> actualResult = result;
			Future<?> drain = executor.submit(() -> {
				while (actualResult.hasNext()) {
					emitted.add(actualResult.next());
				}
			});

			assertTrue(comparisonEntered.await(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS),
					"the natural ORDER stage must enter its value comparator after exhausting input records");
			assertTrue(function.comparisons.get() > 0,
					"the actual native comparator callback reached the blocking RDF value");
			assertTrue(source.opened > openedBeforeNative, "the same invocation opened native statement records");
			boolean cancellationAccepted = cancellation.requestCancellation();
			releaseComparison.countDown();
			drain.get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
			boolean readersClosed = source.opened == source.closed;
			result.close();
			boolean ownerRetired = owner.isClosed();
			assertAll("cancellation during native ORDER comparison",
					() -> assertTrue(cancellationAccepted, "the owning native result admits cancellation"),
					() -> assertTrue(readersClosed, "the cancelled full-sort stage closes its record reader"),
					() -> assertTrue(emitted.isEmpty(), "no row may escape after cancellation while ORDER is sorting"),
					() -> assertTrue(ownerRetired, "closing the cancelled result retires its native owner"));
		} finally {
			releaseComparison.countDown();
			if (result != null) {
				result.close();
			}
			executor.shutdownNow();
			executor.awaitTermination(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
			registry.remove(function);
			if (previousFunction != null) {
				registry.add(previousFunction);
			}
		}
	}

