	private static QueryRoot root(String functionUri, boolean topK) {
		TupleExpr pattern = new org.eclipse.rdf4j.query.algebra.Union(
				new StatementPattern(Var.of("s"),
						Var.of("_predicate", NativeCompositeOriginFixture.iri("p"), true, true),
						Var.of("k")),
				new StatementPattern(Var.of("s"),
						Var.of("_predicate", NativeCompositeOriginFixture.iri("p"), true, true),
						Var.of("k")));
		Projection projection = new Projection(pattern,
				new ProjectionElemList(new ProjectionElem("s"), new ProjectionElem("k")));
		Order order = new Order(projection, List.of(new OrderElem(new FunctionCall(functionUri, Var.of("k")))));
		return new QueryRoot(topK ? new Slice(order, 0L, 2L) : order);
	}

	private static List<Statement> data() {
		var vf = NativeCompositeOriginFixture.VF;
		var predicate = NativeCompositeOriginFixture.iri("p");
		return List.of(vf.createStatement(NativeCompositeOriginFixture.iri("s0"), predicate, vf.createLiteral("a")),
				vf.createStatement(NativeCompositeOriginFixture.iri("s1"), predicate, vf.createLiteral("b")),
				vf.createStatement(NativeCompositeOriginFixture.iri("s2"), predicate, vf.createLiteral("c")));
	}

