	private static final class BlockingIRI implements IRI {
		private static final long serialVersionUID = 1L;
		private final String iri;
		private final CountDownLatch comparisonEntered;
		private final CountDownLatch releaseComparison;
		private final AtomicBoolean blockNextComparison;
		private final AtomicBoolean blocked;
		private final AtomicInteger comparisons;
		private final BooleanSupplier sourceExhausted;

		private BlockingIRI(String label, CountDownLatch comparisonEntered, CountDownLatch releaseComparison,
				AtomicBoolean blockNextComparison, AtomicBoolean blocked, AtomicInteger comparisons,
				BooleanSupplier sourceExhausted) {
			this.iri = "urn:order-cancel-key:" + label;
			this.comparisonEntered = comparisonEntered;
			this.releaseComparison = releaseComparison;
			this.blockNextComparison = blockNextComparison;
			this.blocked = blocked;
			this.comparisons = comparisons;
			this.sourceExhausted = sourceExhausted;
		}

		@Override
		public String stringValue() {
			return iri;
		}

		@Override
		public String getNamespace() {
			return "urn:order-cancel-key:";
		}

		@Override
		public String getLocalName() {
			return iri.substring(getNamespace().length());
		}

		@Override
		public String toString() {
			comparisons.incrementAndGet();
			if (blockNextComparison.get() && sourceExhausted.getAsBoolean()
					&& blocked.compareAndSet(false, true)) {
				comparisonEntered.countDown();
				try {
					if (!releaseComparison.await(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS)) {
						throw new IllegalStateException("timed out waiting for deterministic cancellation release");
					}
				} catch (InterruptedException interrupted) {
					Thread.currentThread().interrupt();
					throw new IllegalStateException("comparison was interrupted before cancellation release",
							interrupted);
				}
			}
			return iri;
		}

		@Override
		public boolean equals(Object other) {
			return other instanceof IRI value && iri.equals(value.stringValue());
		}

		@Override
		public int hashCode() {
			return iri.hashCode();
		}
	}
